FILE engines/glm5-moe-nvfp4-2b/src/kv/page_pool.cc SHA256 b05beb2024b28f59ab5ab986a7637448ff93301eecbc6f5c348a9b5bcb995d6d
#include "kv/page_pool.h"

#include <algorithm>
#include <stdexcept>

namespace rocket::engine::kv {
namespace {

[[noreturn]] void fail(const std::string& what) { throw std::runtime_error("kv: " + what); }

}  // namespace

// ------------------------------------------------------------------ geometry

bool KvGeometry::valid() const { return why_invalid().empty(); }

std::string KvGeometry::why_invalid() const {
  if (page_tokens <= 0) return "page_tokens must be positive";
  if (layers <= 0) return "layers must be positive";
  if (kv_lora <= 0) return "kv_lora must be positive";
  if (index_head_dim <= 0) return "index_head_dim must be positive";
  if (kpool <= 0) return "kpool must be positive";
  if (page_tokens % kpool != 0)
    return "page_tokens must be a multiple of kpool so an indexer pool never straddles a page";
  if (page_bytes() % 65536 != 0)
    return "page slab must be a multiple of the platform's 64 KiB quantum";
  return {};
}

// ------------------------------------------------------------------ PagePool

PagePool::PagePool(int num_pages, int page_tokens)
    : num_pages_(num_pages), page_tokens_(page_tokens) {
  if (num_pages <= 0) fail("num_pages must be positive");
  if (page_tokens <= 0) fail("page_tokens must be positive");
  refcount_.assign(num_pages, 0);
  lru_prev_.assign(num_pages, -1);
  lru_next_.assign(num_pages, -1);
  free_.reserve(num_pages);
  for (int p = num_pages - 1; p >= 0; --p) free_.push_back(p);
}

int PagePool::allocate() {
  if (free_.empty()) return -1;
  const int p = free_.back();
  free_.pop_back();
  refcount_[p] = 1;
  return p;
}

void PagePool::incref(int page) {
  if (page < 0 || page >= num_pages_) fail("incref: page out of range");
  if (refcount_[page] == 0) drop_from_lru(page);
  ++refcount_[page];
}

bool PagePool::decref(int page) {
  if (page < 0 || page >= num_pages_) fail("decref: page out of range");
  if (refcount_[page] <= 0) fail("decref: page is already unreferenced");
  if (--refcount_[page] > 0) return false;
  // Newly evictable: append at the tail, so lru_head_ is the least recently
  // released page and is what reclaim takes first.
  lru_prev_[page] = lru_tail_;
  lru_next_[page] = -1;
  if (lru_tail_ >= 0) lru_next_[lru_tail_] = page;
  lru_tail_ = page;
  if (lru_head_ < 0) lru_head_ = page;
  ++lru_size_;
  return true;
}

int PagePool::refcount(int page) const {
  if (page < 0 || page >= num_pages_) fail("refcount: page out of range");
  return refcount_[page];
}

int PagePool::lru_victim() const { return lru_head_; }

bool PagePool::evict(int page) {
  if (page < 0 || page >= num_pages_) fail("evict: page out of range");
  if (refcount_[page] > 0) return false;
  // Not on the LRU means never allocated: it is already free.
  if (lru_head_ != page && lru_prev_[page] < 0 && lru_next_[page] < 0 && lru_tail_ != page)
    return false;
  drop_from_lru(page);
  free_.push_back(page);
  return true;
}

void PagePool::drop_from_lru(int page) {
  const int prev = lru_prev_[page], next = lru_next_[page];
  if (prev >= 0) lru_next_[prev] = next; else if (lru_head_ == page) lru_head_ = next;
  if (next >= 0) lru_prev_[next] = prev; else if (lru_tail_ == page) lru_tail_ = prev;
  lru_prev_[page] = -1;
  lru_next_[page] = -1;
  if (lru_size_ > 0) --lru_size_;
}

// ---------------------------------------------------------------- PrefixTree

PrefixTree::PrefixTree() {
  nodes_.push_back(Node{});  // root, page -1
  live_nodes_ = 0;
}

std::uint64_t PrefixTree::block_hash(std::uint64_t seed, const int* tokens, int n) {
  std::uint64_t h = seed ^ 0xcbf29ce484222325ull;
  for (int i = 0; i < n; ++i) {
    h ^= static_cast<std::uint64_t>(static_cast<std::uint32_t>(tokens[i]));
    h *= 0x100000001b3ull;
  }
  return h;
}

int PrefixTree::find(int node, std::uint64_t h) const {
  const auto& kids = nodes_[node].children;
  const auto it = kids.find(h);
  return it == kids.end() ? -1 : it->second;
}

int PrefixTree::insert(int node, std::uint64_t h, int page) {
  if (find(node, h) >= 0) fail("insert: edge already present");
  int id;
  if (!free_nodes_.empty()) {
    id = free_nodes_.back();
    free_nodes_.pop_back();
    nodes_[id] = Node{};
  } else {
    id = static_cast<int>(nodes_.size());
    nodes_.push_back(Node{});
  }
  nodes_[id].parent = node;
  nodes_[id].page = page;
  nodes_[id].hash = h;
  nodes_[id].depth = nodes_[node].depth + 1;
  nodes_[node].children.emplace(h, id);
  node_of_page_[page] = id;
  ++live_nodes_;
  return id;
}

void PrefixTree::detach(int node) {
  if (node == kRoot) fail("detach: the root has no page");
  if (!nodes_[node].children.empty()) fail("detach: node still has children");
  const int parent = nodes_[node].parent;
  nodes_[parent].children.erase(nodes_[node].hash);
  node_of_page_.erase(nodes_[node].page);
  nodes_[node] = Node{};
  free_nodes_.push_back(node);
  --live_nodes_;
}

int PrefixTree::node_of_page(int page) const {
  const auto it = node_of_page_.find(page);
  return it == node_of_page_.end() ? -1 : it->second;
}

void PrefixTree::set_page(int node, int page) {
  if (node == kRoot || node < 0 || node >= static_cast<int>(nodes_.size()))
    fail("set_page: node out of range");
  if (page < 0) fail("set_page: page must be non-negative");
  if (nodes_[node].page >= 0) fail("set_page: node already resident");
  if (node_of_page_.count(page)) fail("set_page: page already belongs to another node");
  nodes_[node].page = page;
  node_of_page_[page] = node;
}

void PrefixTree::clear_page(int node) {
  if (node == kRoot || node < 0 || node >= static_cast<int>(nodes_.size()))
    fail("clear_page: node out of range");
  const int page = nodes_[node].page;
  if (page < 0) return;
  node_of_page_.erase(page);
  nodes_[node].page = -1;
}

// ------------------------------------------------------------------- KvCache

KvCache::KvCache(const KvGeometry& geom, PagePool* pool, PrefixTree* tree, PageStore* store,
                 PrefixPageBacking* backing)
    : geom_(geom), pool_(pool), tree_(tree), store_(store), backing_(backing) {
  const std::string bad = geom.why_invalid();
  if (!bad.empty()) fail(bad);
  if (!pool || !tree) fail("KvCache needs a pool and a tree");
  if (pool->page_tokens() != geom.page_tokens) fail("pool and geometry disagree on page_tokens");
}

// A free page, reclaiming the least recently released cached page when the
// free list is empty. Reclaim detaches the tree node first, so the tree never
// names a page whose contents have been handed to another sequence.
int KvCache::take_page() {
  int p = pool_->allocate();
  if (p >= 0) return p;
  for (;;) {
    const int victim = pool_->lru_victim();
    if (victim < 0) return -1;
    const int node = tree_->node_of_page(victim);
    if (node >= 0) {
      const int parent = tree_->parent_of(node);
      const std::uint64_t parent_hash = parent == tree_->root() ? 0 : tree_->hash_of(parent);
      const bool durable = backing_ && backing_->persist_page(
          parent_hash, tree_->hash_of(node), tree_->depth_of(node) * geom_.page_tokens, victim);
      if (durable) {
        // Keep the hash path and descendants. Only GPU residency is released.
        tree_->clear_page(node);
      } else if (tree_->child_count(node) > 0) {
        // Without durable backing an interior page protects its descendants.
        pool_->incref(victim);
        pool_->decref(victim);
        continue;
      } else {
        tree_->detach(node);
      }
    }
    if (!pool_->evict(victim)) fail("lru victim refused eviction");
    p = pool_->allocate();
    if (p >= 0) return p;
  }
}

int KvCache::open(int slot, std::uint64_t hash_seed) {
  int id;
  if (!free_seqs_.empty()) {
    id = free_seqs_.back();
    free_seqs_.pop_back();
    seqs_[id] = Seq{};
  } else {
    id = static_cast<int>(seqs_.size());
    seqs_.push_back(Seq{});
  }
  seqs_[id].live = true;
  seqs_[id].slot = slot;
  seqs_[id].hash_seed = hash_seed;
  if (slot >= 0) {
    // Same occupancy guard as attach(): silently repointing seq_of_slot_ to a
    // new seq while a live sequence still holds the slot leaves that sequence's
    // later detach() erasing the wrong mapping and hands the slot out twice.
    const auto it = seq_of_slot_.find(slot);
    if (it != seq_of_slot_.end())
      fail("open: slot " + std::to_string(slot) + " is held by seq " +
           std::to_string(it->second) + "; detach it first");
    seq_of_slot_[slot] = id;
  }
  return id;
}

int KvCache::open_shared(int slot, const int* tokens, int n_tokens, int* matched_tokens_out,
                         std::uint64_t hash_seed) {
  const int id = open(slot, hash_seed);
  Seq& s = seqs_[id];
  const int P = geom_.page_tokens;
  int node = tree_->root();
  std::uint64_t seed = hash_seed;
  int matched = 0;
  while (matched + P <= n_tokens) {
    const std::uint64_t h = PrefixTree::block_hash(seed, tokens + matched, P);
    int child = tree_->find(node, h);
    int page = child < 0 ? -1 : tree_->page_of(child);
    const std::uint64_t record_parent = matched == 0 ? 0 : seed;
    if (child < 0) {
      if (!backing_ || !backing_->holds_page(record_parent, h, matched + P)) break;
      page = take_page();
      if (page < 0 || !backing_->restore_page(record_parent, h, matched + P, page)) {
        if (page >= 0) {
          pool_->decref(page);
          pool_->evict(page);
        }
        break;
      }
      child = tree_->insert(node, h, page);
    } else if (page < 0) {
      page = take_page();
      if (page < 0 || !backing_ ||
          !backing_->restore_page(record_parent, h, matched + P, page)) {
        if (page >= 0) {
          pool_->decref(page);
          pool_->evict(page);
        }
        break;
      }
      tree_->set_page(child, page);
    } else {
      pool_->incref(page);
    }
    s.pages.push_back(page);
    s.nodes.push_back(child);
    s.tokens.insert(s.tokens.end(), tokens + matched, tokens + matched + P);
    s.length += P;
    node = child;
    seed = h;
    matched += P;
  }
  if (matched_tokens_out) *matched_tokens_out = matched;
  return id;
}

std::uint64_t KvCache::hash_at(int seq, int token_count) const {
  const Seq& s = seqs_.at(seq);
  if (!s.live || token_count < 0 || token_count > s.length ||
      token_count % geom_.page_tokens != 0)
    fail("hash_at: boundary is not a live full-page prefix");
  if (token_count == 0) return 0;
  const int node = s.nodes.at(token_count / geom_.page_tokens - 1);
  if (node < 0) fail("hash_at: prefix page is not sealed");
  return tree_->hash_of(node);
}

bool KvCache::persist(int seq) {
  if (!backing_) return false;
  const Seq& s = seqs_.at(seq);
  if (!s.live) fail("persist: sequence is not live");
  for (std::size_t i = 0; i < s.nodes.size(); ++i) {
    const int node = s.nodes[i];
    if (node < 0) continue;
    const int page = tree_->page_of(node);
    if (page < 0) continue;
    const int parent = tree_->parent_of(node);
    const std::uint64_t parent_hash = parent == tree_->root() ? 0 : tree_->hash_of(parent);
    if (!backing_->persist_page(parent_hash, tree_->hash_of(node),
                                static_cast<int>((i + 1) * geom_.page_tokens), page))
      return false;
  }
  return true;
}

int KvCache::fork(int parent, int fork_pos, int slot) {
  if (parent < 0 || parent >= static_cast<int>(seqs_.size()) || !seqs_[parent].live)
    fail("fork: parent is not a live sequence");
  if (fork_pos < 0 || fork_pos > seqs_[parent].length)
    fail("fork: fork_pos outside the parent's sequence");

  const int P = geom_.page_tokens;
  const int n_pages = (fork_pos + P - 1) / P;
  const int n_full = fork_pos / P;

  // Snapshot what the child inherits before open(), which can grow seqs_ and
  // invalidate any reference into it.
  std::vector<int> pages(seqs_[parent].pages.begin(), seqs_[parent].pages.begin() + n_pages);
  std::vector<int> nodes(n_pages, -1);
  for (int i = 0; i < n_full; ++i) nodes[i] = seqs_[parent].nodes[i];
  std::vector<int> toks(seqs_[parent].tokens.begin(), seqs_[parent].tokens.begin() + fork_pos);

  const int id = open(slot, seqs_[parent].hash_seed);
  Seq& c = seqs_[id];
  for (const int page : pages) pool_->incref(page);
  c.pages = std::move(pages);
  c.nodes = std::move(nodes);
  c.tokens = std::move(toks);
  c.length = fork_pos;
  return id;
}

AppendSite KvCache::append_token(int seq, int token_id) {
  if (seq < 0 || seq >= static_cast<int>(seqs_.size()) || !seqs_[seq].live)
    fail("append_token: not a live sequence");
  Seq& s = seqs_[seq];
  const int P = geom_.page_tokens;
  const int li = s.length / P;
  const int off = s.length % P;

  AppendSite site;
  site.logical_page = li;
  site.slot = off;

  if (off == 0) {
    const int p = take_page();
    if (p < 0) return site;  // page == -1, nothing mutated
    s.pages.push_back(p);
    s.nodes.push_back(-1);
    site.page = p;
    site.grew_table = true;
  } else {
    int p = s.pages[li];
    if (pool_->refcount(p) > 1) {
      // Copy on extend: the partial boundary page a fork left shared. The
      // first writer takes a private copy; the other side keeps the original.
      const int q = take_page();
      if (q < 0) return site;
      if (!store_) fail("append_token: copy on extend needs a PageStore");
      store_->copy_page(q, p);
      pool_->decref(p);
      s.pages[li] = q;
      p = q;
      site.copied_on_extend = true;
    }
    site.page = p;
  }

  s.tokens.push_back(token_id);
  ++s.length;
  if (s.length % P == 0) {
    seal(seq, li);
    site.sealed_page = true;
  }
  return site;
}

void KvCache::truncate(int seq, int new_len) {
  if (seq < 0 || seq >= static_cast<int>(seqs_.size()) || !seqs_[seq].live)
    fail("truncate: not a live sequence");
  Seq& s = seqs_[seq];
  const int P = geom_.page_tokens;
  if (new_len > s.length || new_len < 0) fail("truncate: new_len out of range");
  if (new_len == s.length) return;
  const int keep = (new_len + P - 1) / P;
  for (int li = static_cast<int>(s.pages.size()) - 1; li >= keep; --li) {
    if (s.nodes[li] >= 0 && tree_->child_count(s.nodes[li]) == 0)
      tree_->detach(s.nodes[li]);
    pool_->decref(s.pages[li]);
  }
  s.pages.resize(keep);
  s.nodes.resize(keep);
  s.tokens.resize(new_len);
  s.length = new_len;
}

// A page that just filled becomes a tree node, keyed by the hash of its token
// block seeded with its parent node's hash. The node makes the page findable
// by open_shared() and orders eviction: a page with cached descendants cannot
// be reclaimed before them.
void KvCache::seal(int seq, int logical_page) {
  Seq& s = seqs_[seq];
  const int P = geom_.page_tokens;
  const int parent_node = logical_page == 0 ? tree_->root() : s.nodes[logical_page - 1];
  if (parent_node < 0) return;  // a forked, still-unsealed ancestor: not indexable
  const std::uint64_t seed =
      parent_node == tree_->root() ? s.hash_seed : tree_->hash_of(parent_node);
  const std::uint64_t h =
      PrefixTree::block_hash(seed, s.tokens.data() + static_cast<std::size_t>(logical_page) * P, P);
  const int existing = tree_->find(parent_node, h);
  if (existing >= 0) {
    // Another sequence already indexed an identical block under this prefix.
    // Keep our own page and leave the edge alone: merging would assume the
    // two pages hold identical bytes, which is only true if the KV was
    // computed batch-invariantly. open_shared() is where that assumption is
    // taken on purpose.
    return;
  }
  s.nodes[logical_page] = tree_->insert(parent_node, h, s.pages[logical_page]);
}

void KvCache::detach(int seq) {
  if (seq < 0 || seq >= static_cast<int>(seqs_.size()) || !seqs_[seq].live)
    fail("detach: not a live sequence");
  Seq& s = seqs_[seq];
  if (s.slot >= 0) seq_of_slot_.erase(s.slot);
  s.slot = -1;
}

void KvCache::attach(int seq, int slot) {
  if (seq < 0 || seq >= static_cast<int>(seqs_.size()) || !seqs_[seq].live)
    fail("attach: not a live sequence");
  if (slot < 0) fail("attach: slot must be non-negative");
  const auto it = seq_of_slot_.find(slot);
  if (it != seq_of_slot_.end() && it->second != seq) fail("attach: slot is already occupied");
  Seq& s = seqs_[seq];
  if (s.slot >= 0) seq_of_slot_.erase(s.slot);
  s.slot = slot;
  seq_of_slot_[slot] = seq;
}

void KvCache::destroy(int seq) {
  if (seq < 0 || seq >= static_cast<int>(seqs_.size()) || !seqs_[seq].live)
    fail("destroy: not a live sequence");
  Seq& s = seqs_[seq];
  // Release private/generated tail pages first and shared prompt ancestors
  // last. The LRU therefore evicts output branches before reusable prompts.
  for (auto it = s.pages.rbegin(); it != s.pages.rend(); ++it) pool_->decref(*it);
  if (s.slot >= 0) seq_of_slot_.erase(s.slot);
  s = Seq{};
  free_seqs_.push_back(seq);
}

const std::vector<int>& KvCache::page_table(int seq) const { return seqs_.at(seq).pages; }
const std::vector<int>& KvCache::tokens(int seq) const { return seqs_.at(seq).tokens; }

SeqInfo KvCache::info(int seq) const {
  const Seq& s = seqs_.at(seq);
  return SeqInfo{s.length, s.slot, static_cast<int>(s.pages.size()), s.live};
}

int KvCache::slot_of(int seq) const { return seqs_.at(seq).slot; }

int KvCache::seq_in_slot(int slot) const {
  const auto it = seq_of_slot_.find(slot);
  return it == seq_of_slot_.end() ? -1 : it->second;
}

}  // namespace rocket::engine::kv


FILE engines/glm5-moe-nvfp4-2b/src/kv/page_pool.h SHA256 a69304e79ffe64291468c649fbc14cc65743ee14131801a0a470195aaf8d3052
// Refcounted fixed-size KV pages, a page-granularity radix tree over token
// sequences, and the sequence manager that forks, detaches, resumes, and
// destroys streams on top of them.
//
// Stage 1 gave every stream slot one physical page sized to the whole context
// (model.cu, KvPages with max_pages = 1). The kernels were already written
// against a block table: every KV-touching kernel resolves a logical position
// through kv_locate(kv, m, pos) -> (physical page, slot in page), so the
// gather and the indexer scan already iterate through a page table. What was
// missing is a pool behind that table with more than one page per stream, and
// the host bookkeeping that lets two streams name the same physical page.
//
// Sharing model. A page is shared only when two sequences literally point at
// the same bytes, which happens exactly one way: fork(parent, pos) hands the
// child the parent's full pages below `pos` and increments their refcounts.
// The boundary page, partially filled at the fork point, is copied the first
// time either side extends into it (copy on extend). Content-addressed reuse
// across sequences that were computed independently is a separate, opt-in
// entry point; see open_shared().
//
// Everything here is host bookkeeping. It runs once per appended token (an
// index computation) and once per sealed page (a hash over page_tokens ids),
// never per layer and never per gathered token. Device work is confined to
// the PageStore interface: one page copy on extend, and the table upload.
#pragma once

#include <cstddef>
#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

namespace rocket::engine::kv {

// Byte geometry of one page, in the layout kernels.cu already reads:
//   latent[page][layers][page_tokens][kv_lora]
//   key   [page][layers][page_tokens][index_head_dim]
//   gate  [page][layers][page_tokens][index_head_dim]
// so one page carries every MLA layer's slice of the same token range and a
// single refcount covers all 11 layers at once.
struct KvGeometry {
  int page_tokens = 0;
  int layers = 0;           // MLA layer count, 11 for this fuel
  int kv_lora = 0;          // 512
  int index_head_dim = 0;   // 128
  int kpool = 0;            // 4, indexer pool width

  // Bytes of latent + key + gate for one page, BF16 throughout.
  std::size_t page_bytes() const {
    const std::size_t per_token = static_cast<std::size_t>(kv_lora) * 2 +
                                  static_cast<std::size_t>(index_head_dim) * 2 * 2;
    return per_token * static_cast<std::size_t>(page_tokens) *
           static_cast<std::size_t>(layers);
  }
  std::size_t bytes_per_token() const { return page_bytes() / static_cast<std::size_t>(page_tokens); }

  // Two constraints on page_tokens, both structural rather than tuning:
  //  - a multiple of kpool, because indexer_pool_kernel reads the kpool
  //    tokens of a pool as one run and a pool must not straddle two pages;
  //  - a multiple of 128, because 16896 B/token * 128 is 2 MiB and every
  //    smaller multiple leaves a page slab unaligned to the platform's
  //    64 KiB quantum (blog/rocket.qmd#alignment).
  bool valid() const;
  std::string why_invalid() const;
};

// Device-side operations the sequence manager needs. Implemented by KvArena
// (kv_arena.h) against the real slabs; a test can substitute a host double.
class PageStore {
 public:
  virtual ~PageStore() = default;
  // Byte copy of every layer's slice of page `src` into page `dst`.
  virtual void copy_page(int dst, int src) = 0;
};

// Physical page allocator. Pages carry a refcount; a page whose refcount
// reaches zero is not returned to the free list, it moves to the tail of an
// LRU of evictable pages so a later sequence with the same prefix can still
// find it in the tree. Reclaiming one is an explicit act.
class PagePool {
 public:
  PagePool(int num_pages, int page_tokens);

  int num_pages() const { return num_pages_; }
  int page_tokens() const { return page_tokens_; }

  // A page with refcount 1, taken from the free list. -1 when the free list
  // is empty; the caller decides whether to reclaim_lru() and try again.
  int allocate();
  void incref(int page);
  // Returns true when the refcount reached zero and the page became
  // evictable. Never frees: the page keeps its contents and its tree node.
  bool decref(int page);
  int refcount(int page) const;

  // Refuses (returns false) while the page is referenced by any sequence.
  // On success the page leaves the evictable LRU and rejoins the free list;
  // the caller must detach its tree node first, or the tree will name a page
  // whose contents have been handed to someone else.
  bool evict(int page);
  // Least recently released evictable page, or -1. Does not evict it.
  int lru_victim() const;

  int free_pages() const { return static_cast<int>(free_.size()); }
  int evictable_pages() const { return static_cast<int>(lru_size_); }
  int pinned_pages() const { return num_pages_ - free_pages() - evictable_pages(); }

 private:
  void drop_from_lru(int page);

  int num_pages_ = 0;
  int page_tokens_ = 0;
  std::vector<int> refcount_;
  std::vector<int> free_;
  // Intrusive doubly-linked LRU over page ids; -1 terminates.
  std::vector<int> lru_prev_, lru_next_;
  int lru_head_ = -1, lru_tail_ = -1;
  std::size_t lru_size_ = 0;
};

// Radix tree over token sequences at page granularity: one node per full
// page, the edge from a parent node keyed by a 64-bit hash of that page's
// token block. A sequence's full pages are exactly a root-to-node path, which
// is why fork sharing and prefix lookup are the same structure.
class PrefixTree {
 public:
  PrefixTree();

  static constexpr int kRoot = 0;
  int root() const { return kRoot; }

  // Child of `node` whose page block hashes to `h`, or -1.
  int find(int node, std::uint64_t h) const;
  // Adds `page` as a child of `node` under `h` and returns the new node.
  int insert(int node, std::uint64_t h, int page);
  // Removes `node` from its parent and recycles it. Only legal for a leaf,
  // which is what eviction produces: a page is evictable only when no
  // sequence holds it, and a node with children has a descendant page a
  // sequence still holds, or a cached descendant that must go first.
  void detach(int node);

  int page_of(int node) const { return nodes_[node].page; }
  int parent_of(int node) const { return nodes_[node].parent; }
  // A disk-backed node remains in the radix tree while its GPU page is -1.
  // set_page() attaches a freshly restored physical page; clear_page()
  // removes only the page mapping and preserves the hash path.
  void set_page(int node, int page);
  void clear_page(int node);
  int child_count(int node) const { return static_cast<int>(nodes_[node].children.size()); }
  int depth_of(int node) const { return nodes_[node].depth; }
  int node_of_page(int page) const;
  int live_nodes() const { return live_nodes_; }

  // Hash of one page-sized block of token ids. FNV-1a over the ids, seeded
  // with the parent node's own hash so the same block under a different
  // prefix is a different edge.
  static std::uint64_t block_hash(std::uint64_t seed, const int* tokens, int n);
  std::uint64_t hash_of(int node) const { return nodes_[node].hash; }

 private:
  struct Node {
    int parent = -1;
    int page = -1;
    std::uint64_t hash = 0;
    int depth = 0;
    std::unordered_map<std::uint64_t, int> children;
  };
  std::vector<Node> nodes_;
  std::vector<int> free_nodes_;
  std::unordered_map<int, int> node_of_page_;
  int live_nodes_ = 0;
};

// What append_token() decided, so the caller knows where to write this
// step's latent/key/gate and whether the page table changed.
struct AppendSite {
  int page = -1;         // physical page the write lands in
  int slot = -1;         // token slot inside that page
  int logical_page = -1; // index into the sequence's page table
  bool grew_table = false;   // a new page was appended to the table
  bool copied_on_extend = false;  // a shared partial page was copied first
  bool sealed_page = false;  // this token filled `logical_page`
};

// One sequence's view of the pool. `slot` is the engine stream slot it
// currently occupies, or -1 while detached.
struct SeqInfo {
  int length = 0;
  int slot = -1;
  int pages = 0;
  bool live = false;
};

// Optional persistence seam for a radix page. Implementations receive the
// exact parent-seeded hash and the final-layout physical page. A successful
// persist lets KvCache retain the radix node after releasing its GPU page.
class PrefixPageBacking {
 public:
  virtual ~PrefixPageBacking() = default;
  virtual bool holds_page(std::uint64_t parent_hash, std::uint64_t chain_hash,
                          int token_count) const = 0;
  virtual bool persist_page(std::uint64_t parent_hash, std::uint64_t chain_hash,
                            int token_count, int page) = 0;
  virtual bool restore_page(std::uint64_t parent_hash, std::uint64_t chain_hash,
                            int token_count, int page) = 0;
};

// Sequence manager: the object model.cu holds instead of a table of identity.
class KvCache {
 public:
  // `store` may be null only when no copy on extend can happen, which is not
  // a case worth special-casing; pass the arena.
  KvCache(const KvGeometry& geom, PagePool* pool, PrefixTree* tree, PageStore* store,
          PrefixPageBacking* backing = nullptr);

  // A fresh empty sequence bound to stream slot `slot` (-1 for detached).
  int open(int slot, std::uint64_t hash_seed = 0);
  // A fresh sequence that adopts whatever prefix of `tokens` the tree already
  // holds, then continues as a normal sequence. This is content-addressed
  // reuse across sequences that were computed independently, and it is a
  // separate entry point on purpose: it is exact only if identical token
  // prefixes produce identical KV bytes, which holds for every kernel in this
  // engine except the grouped-GEMM routed-expert path, whose row grouping
  // depends on the batch it ran in (moe_grouped.h). fork() carries no such
  // condition because it shares the bytes themselves.
  int open_shared(int slot, const int* tokens, int n_tokens, int* matched_tokens_out,
                  std::uint64_t hash_seed = 0);
  // Writes every sealed page of a sequence through PrefixPageBacking. Returns
  // false when no backing is configured or any page fails to persist.
  bool persist(int seq);
  // Parent-seeded hash at a full-page token boundary, or 0 at the root.
  std::uint64_t hash_at(int seq, int token_count) const;

  // Child sharing every full page of `parent` below `fork_pos`. The boundary
  // page is shared too and copied by whichever side extends into it first.
  // Returns -1 when the pool cannot back the child's page table.
  int fork(int parent, int fork_pos, int slot);

  // Reserves the site for one more token and returns where to write it.
  // `page` is -1 when the pool is exhausted; nothing is mutated in that case.
  AppendSite append_token(int seq, int token_id);
  // Drops every reserved site beyond `new_len`. Rejected spec drafts leave
  // stale KV in the pages they were given; truncating releases those pages
  // and rewinds the sequence so the indexer never reads them.
  void truncate(int seq, int new_len);

  // Frees the stream slot, keeps every page. The caller is responsible for
  // the KDA state (KdaStateStore, kv_arena.h): it is per stream, 72.8 MiB,
  // and not shareable, so it has to leave the device with the slot.
  void detach(int seq);
  void attach(int seq, int slot);

  // Drops this sequence's claim on its pages. Pages whose refcount reaches
  // zero stay in the tree as cache until something reclaims them.
  void destroy(int seq);

  const std::vector<int>& page_table(int seq) const;
  const std::vector<int>& tokens(int seq) const;
  SeqInfo info(int seq) const;
  int slot_of(int seq) const;
  int seq_in_slot(int slot) const;

  // Physical pages currently referenced by at least one live sequence.
  int pinned_pages() const { return pool_->pinned_pages(); }
  const KvGeometry& geometry() const { return geom_; }
  void set_backing(PrefixPageBacking* backing) { backing_ = backing; }

 private:
  int take_page();
  void seal(int seq, int logical_page);

  struct Seq {
    std::vector<int> pages;   // logical page -> physical page
    std::vector<int> nodes;   // logical page -> tree node, -1 while unsealed
    std::vector<int> tokens;  // full token history, for hashing and forks
    int length = 0;
    int slot = -1;
    bool live = false;
    std::uint64_t hash_seed = 0;
  };

  KvGeometry geom_;
  PagePool* pool_ = nullptr;
  PrefixTree* tree_ = nullptr;
  PageStore* store_ = nullptr;
  PrefixPageBacking* backing_ = nullptr;
  std::vector<Seq> seqs_;
  std::vector<int> free_seqs_;
  std::unordered_map<int, int> seq_of_slot_;
};

}  // namespace rocket::engine::kv


