bool NvmeArenaPageBacking::holds_page(std::uint64_t parent_hash,
                                      std::uint64_t chain_hash,
                                      int token_count) const {
  const bool hit = store_.holds(key(parent_hash, chain_hash, token_count));
  store_.note_page_lookup(hit);
