        static_cast<std::size_t>(heads_kda) * hd * hd * sizeof(bf16);
    const std::size_t conv_per_layer =
        3ull * cfg_.kda_qkv_dim() * cfg_.conv_state_taps() * sizeof(bf16);
    if (recurrent_per_layer != 2097152ull || conv_per_layer != 147456ull)
