  q_conv_ = A(static_cast<std::size_t>(SB) * qkv);
  k_conv_ = A(static_cast<std::size_t>(SB) * qkv);
  v_conv_ = A(static_cast<std::size_t>(SB) * qkv);
  lr_a_ = A(static_cast<std::size_t>(SB) * hd);
  lr_b_ = A(static_cast<std::size_t>(SB) * qkv);
