  if (max_batch_ <= 0) fail("max_batch must be positive");
  if (max_prefill_chunk < 1 || max_prefill_chunk > 64)
    fail("max_prefill_chunk must be in [1,64]");
  cuda_check(cudaStreamCreate(&stream_), "stream");

