  double norm = 0.0;
  for (int t = 0; t < K; ++t) norm += wts[static_cast<std::size_t>(t)];
  for (int t = 0; t < K; ++t) {
    const double pr = wts[static_cast<std::size_t>(t)] / (norm > 0.0 ? norm : 1.0);
    if (pr > 0.0) ent -= pr * std::log(pr);
