  if (moe_path_ != MoePath::kForceGemv && want_grouped) {
    if (!run_moe_grouped(layer, batch, idx, wts)) {
      cudaMemsetAsync(acc_, 0, static_cast<std::size_t>(batch) * H * sizeof(bf16), stream_);
      run_moe_gemv(layer, batch, idx);
    }
